const $=s=>document.querySelector(s),ui={hud:$("#hud"),skillHud:$("#skillHud"),touch:$("#touchControls"),announcement:$("#announcement"),pHp:$("#pHp"),eHp:$("#eHp"),pEnergy:$("#pEnergy"),eEnergy:$("#eEnergy"),timer:$("#timer")};

function showScreen(name){document.querySelectorAll(".screen").forEach(e=>e.classList.remove("active"));if(name)$(`#${name}`).classList.add("active");mode=name||"battle";ui.hud.hidden=mode!=="battle";ui.skillHud.hidden=true;ui.touch.hidden=true;$("#soundBtn").hidden=mode==="battle";$("#pauseBtn").hidden=mode!=="battle"}
function buildRoster(){const roster=$("#roster"),online=$("#onlineFighter");roster.replaceChildren();online.replaceChildren();fighters.forEach((f,i)=>{const b=document.createElement("button");b.className="fighter-card";b.innerHTML=`<canvas width="180" height="180"></canvas><span>${f.name}</span>`;drawPortrait(b.querySelector("canvas").getContext("2d"),f);b.onclick=()=>selectFighter(i,b);roster.append(b);const option=document.createElement("option");option.value=i;option.textContent=`${f.name} · ${f.title}`;online.append(option)});drawLargePreview($("#ePreview"),fighters[1],-1)}
function selectFighter(i,card){selected=i;document.querySelectorAll(".fighter-card").forEach(e=>e.classList.remove("selected"));card.classList.add("selected");const f=fighters[i],rival=fighters[(i+1)%fighters.length];$(".select-header h2").textContent=f.name;$("#fighterDetail").innerHTML=`<strong>${f.title}</strong> · 체력 ${fighterMaxHp(f)} · ${f.desc}<br>E ${f.skills[0]} (0) / R ${f.skills[1]} (${f.costs[1]}) / T ${f.skills[2]} (${f.costs[2]})`;$("#fightBtn").disabled=false;drawLargePreview($("#pPreview"),f,1);drawLargePreview($("#ePreview"),rival,-1);tone(380,.05,"square")}
function drawPortrait(g,f){g.fillStyle="#fff";g.fillRect(0,0,180,180);drawFighter(g,90,96,1.55,f,1,0,true)}
function drawLargePreview(canvas,f,face){const g=canvas.getContext("2d");g.clearRect(0,0,canvas.width,canvas.height);drawFighter(g,canvas.width/2,128,2.05,f,face,0,true)}
function drawHudIcon(canvas,f,face){const g=canvas.getContext("2d");g.clearRect(0,0,canvas.width,canvas.height);g.fillStyle="#49384f";g.fillRect(0,0,canvas.width,canvas.height);drawFighter(g,canvas.width/2,canvas.height/2,.7,f,face,0,true)}
function fighterMaxHp(f){return f.hp||(["hammer","spear","blade","glove","shield","katana","scythe"].includes(f.weapon)?150:105)}
function actor(f,x,facing,ai=false,remote=false){const maxHp=fighterMaxHp(f);return{fighter:f,x,y:FLOOR-24,vx:0,vy:0,facing,isAI:ai,isRemote:remote,hp:maxHp,maxHp,energy:100,radius:24,onGround:true,skillDelay:[0,0,0],hurt:0,flash:0,attackPose:0,invuln:0,aiThink:.75,ultimate:null,ultTime:0,ultTrail:[],ultTrailTime:0,ko:false}}
function resetMatch(left,right,remote=false){player=actor(fighters[left],100,1);enemy=actor(fighters[right],1080,-1,false,remote);cameraX=0;projectiles=[];particles=[];damageTexts=[];matchTime=99;elapsed=0;hits=0;paused=false;roundLive=false;$("#pName").textContent=player.fighter.name;$("#eName").textContent=enemy.fighter.name;drawHudIcon($("#pIcon"),player.fighter,1);drawHudIcon($("#eIcon"),enemy.fighter,-1);showScreen()}
function startBattle(){battleType="ai";netRole=null;closeNetwork();resetMatch(selected,(selected+1)%fighters.length);enemy.isAI=true;announce("READY",800,()=>announce("FIGHT!",650,()=>roundLive=true))}
function announce(text,time,done){ui.announcement.textContent=text;ui.announcement.hidden=false;setTimeout(()=>{ui.announcement.hidden=true;if(done)done()},time)}
function roomId(code){return`rift-bounce-${code.toLowerCase()}`}
function randomCode(){const chars="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";return Array.from({length:6},()=>chars[Math.floor(Math.random()*chars.length)]).join("")}
function networkMessage(text,error=false){$("#networkStatus").textContent=text;$("#networkStatus").classList.toggle("error",error)}
function closeNetwork(){if(conn){conn.close();conn=null}if(peer){peer.destroy();peer=null}remoteKeys=Object.create(null);remotePressed=Object.create(null)}
function createRoom(){if(typeof Peer==="undefined"){networkMessage("온라인 모듈을 불러오지 못했습니다. 인터넷 연결을 확인하세요.",true);return}closeNetwork();battleType="online";netRole="host";const code=randomCode();$("#roomCode").textContent=code;$("#roomInfo").hidden=false;networkMessage("연결 서버에 접속 중...");peer=new Peer(roomId(code));peer.on("open",()=>networkMessage("친구가 참가할 때까지 기다리는 중입니다."));peer.on("connection",c=>{if(conn){c.close();return}conn=c;setupConnection(c)});peer.on("error",()=>networkMessage("방을 만들지 못했습니다. 잠시 뒤 다시 시도하세요.",true))}
function joinRoom(){if(typeof Peer==="undefined"){networkMessage("온라인 모듈을 불러오지 못했습니다.",true);return}const code=$("#roomCodeInput").value.trim().toUpperCase();if(code.length!==6){networkMessage("6자리 방 코드를 입력하세요.",true);return}closeNetwork();battleType="online";netRole="guest";networkMessage("방에 연결 중...");peer=new Peer();peer.on("open",()=>{conn=peer.connect(roomId(code),{reliable:true,serialization:"json"});setupConnection(conn)});peer.on("error",()=>networkMessage("방을 찾지 못했거나 연결할 수 없습니다.",true))}
function setupConnection(c){c.on("open",()=>{networkMessage("상대와 연결됐습니다. 대전을 준비합니다.");const fighter=Number($("#onlineFighter").value);if(netRole==="guest")c.send({type:"ready",fighter})});c.on("data",handleNetworkData);c.on("close",()=>{if(mode==="battle"){roundLive=false;announce("연결 종료",1200,()=>showScreen("online"))}networkMessage("상대의 연결이 종료됐습니다.",true)});c.on("error",()=>networkMessage("상대와 연결하지 못했습니다.",true))}
function handleNetworkData(data){if(!data||!data.type)return;if(netRole==="host"&&data.type==="ready"){const mine=Number($("#onlineFighter").value);resetMatch(mine,data.fighter,true);conn.send({type:"start",hostFighter:mine,guestFighter:data.fighter});announce("READY",800,()=>announce("FIGHT!",650,()=>roundLive=true));return}if(netRole==="guest"&&data.type==="start"){resetMatch(data.hostFighter,data.guestFighter);announce("READY",800,()=>announce("FIGHT!",650,()=>roundLive=true));return}if(netRole==="host"&&data.type==="input"){remoteKeys[data.key]=data.down;if(data.down)remotePressed[data.key]=true;return}if(netRole==="guest"&&data.type==="state")applyState(data);if(data.type==="finish"&&netRole==="guest")showResult(!data.hostWon)}
function actorState(a){return{x:a.x,y:a.y,vx:a.vx,vy:a.vy,facing:a.facing,hp:a.hp,maxHp:a.maxHp,energy:a.energy,skillDelay:a.skillDelay,hurt:a.hurt,flash:a.flash,attackPose:a.attackPose,ultimate:a.ultimate,ultTime:a.ultTime,ultTrail:a.ultTrail,ultTrailTime:a.ultTrailTime,ko:a.ko}}
function applyState(s){if(!player||!enemy)return;const oldPlayerHp=player.hp,oldEnemyHp=enemy.hp;Object.assign(player,s.player);Object.assign(enemy,s.enemy);if(player.hp<oldPlayerHp)showDamage(player,oldPlayerHp-player.hp);if(enemy.hp<oldEnemyHp)showDamage(enemy,oldEnemyHp-enemy.hp);matchTime=s.matchTime;elapsed=s.elapsed;projectiles=s.projectiles.map(p=>({...p,owner:p.owner===0?player:enemy}));updateBattleUI()}
function sendState(now){if(netRole!=="host"||!conn?.open||now-lastSync<50)return;lastSync=now;conn.send({type:"state",player:actorState(player),enemy:actorState(enemy),matchTime,elapsed,projectiles:projectiles.map(p=>({x:p.x,y:p.y,startX:p.startX,maxDistance:p.maxDistance,vx:p.vx,vy:p.vy,radius:p.radius,maxRadius:p.maxRadius,blastRadius:p.blastRadius,age:p.age,life:p.life,damage:p.damage,force:p.force,color:p.color,style:p.style,delay:p.delay,trail:p.trail,trailTime:p.trailTime,owner:p.owner===player?0:1}))})}

function shot(a,style,vx,vy,radius,life,damage,force,color=a.fighter.accent,x=a.x+a.facing*45,y=a.y,maxDistance=Infinity){projectiles.push({owner:a,style,x,y,startX:x,vx:a.facing*vx,vy,radius,baseRadius:radius,life,damage:damage*a.fighter.power,force,color,maxDistance,trail:[],trailTime:0,flightAge:0,effectTime:0,phase:Math.random()*Math.PI*2})}
function areaAttack(a,radius,damage,force,style="ultBlast"){const target=a===player?enemy:player,distance=Math.hypot(target.x-a.x,target.y-a.y);projectiles.push({owner:a,style,x:a.x,y:a.y,vx:0,vy:0,radius:18,maxRadius:radius,age:0,life:.58,damage:0,force:0,color:a.fighter.accent});if(distance<radius)hit(target,a,radialDamage(damage*a.fighter.power,distance,radius),force);shake=Math.min(22,8+damage*.35);burst(a.x,a.y,a.fighter.accent,24)}
function castMove(a,move){const target=a===player?enemy:player,color=a.fighter.accent,speed=move.speed||600,radius=move.radius||12,life=move.life||1.3,damage=move.damage||8,force=move.force||320,rangeLimit=move.mode==="beam"?650:move.mode==="spread"||move.mode==="recoil"?480:520,range=Math.min(move.range??rangeLimit,rangeLimit);if(move.mode==="shot"||move.mode==="beam"){shot(a,move.style||"orb",speed,0,radius,life,damage,force,color,a.x+a.facing*42,a.y,range);return}if(move.mode==="spread"||move.mode==="recoil"){const count=move.count||3,spread=move.spread||120;for(let i=0;i<count;i++){const offset=count===1?0:(i/(count-1)-.5)*spread;shot(a,move.style||"bullet",speed,offset,radius,life,damage,force,color,a.x+a.facing*42,a.y+offset*.05,range)}if(move.mode==="recoil"){a.vx=-a.facing*(move.recoil||310);burst(a.x+a.facing*32,a.y,color,12)}return}if(move.mode==="boomerang"){shot(a,move.style||"disc",speed,0,radius,Math.max(life,2.2),damage,force,color,a.x+a.facing*42,a.y,range);const p=projectiles[projectiles.length-1];p.canReturn=true;p.returnRange=range;p.pierceReturn=true;return}if(move.mode==="mark"){projectiles.push({owner:a,style:"mark",x:target.x,y:target.y,vx:0,vy:0,radius:6,maxRadius:28,blastRadius:move.radius||165,age:0,life:(move.delay||1.5)+.12,delay:move.delay||1.5,damage,force,color});return}if(move.mode==="mine"){const delay=move.delay||1.55;projectiles.push({owner:a,style:"mine",x:Math.max(35,Math.min(WORLD_W-35,a.x+a.facing*115)),y:FLOOR-16,vx:0,vy:0,radius:16,blastRadius:move.radius||150,age:0,life:delay+.18,delay,damage:damage*a.fighter.power,force,color});burst(a.x+a.facing*50,a.y+10,color,10);return}if(move.mode==="pull"){const fieldRadius=move.radius||210,distance=Math.hypot(target.x-a.x,target.y-a.y);projectiles.push({owner:a,style:"ultBlast",x:a.x,y:a.y,vx:0,vy:0,radius:24,maxRadius:fieldRadius,age:0,life:.58,damage:0,force:0,color});if(distance<fieldRadius){hit(target,a,damage*a.fighter.power,-Math.abs(force));target.vy=-90}shake=10;return}if(move.mode==="nova"){areaAttack(a,move.radius||220,damage,force);return}if(move.mode==="shield"){a.invuln=Math.max(a.invuln,move.duration||1.2);projectiles.push({owner:a,style:"shield",x:a.x,y:a.y,vx:0,vy:0,radius:42,maxRadius:58,age:0,life:move.duration||1.2,damage:0,force:0,color});burst(a.x,a.y,color,16);return}if(move.mode==="dash"){a.vx=a.facing*(move.distance||260)*3.2;shot(a,move.style||"slash",760,0,30,.22,damage,force,color,a.x+a.facing*48,a.y,180);return}if(move.mode==="blink"){const oldX=a.x;a.x=Math.max(42,Math.min(WORLD_W-42,a.x+a.facing*(move.distance||280)));burst(oldX,a.y,color,14);burst(a.x,a.y,color,18);const distance=Math.hypot(target.x-a.x,target.y-a.y);if(distance<88)hit(target,a,damage*a.fighter.power,force);return}if(move.mode==="rain"){const count=move.count||5;for(let i=0;i<count;i++){const x=target.x+(i-(count-1)/2)*58;projectiles.push({owner:a,style:"meteor",x,y:-50-Math.abs(i-(count-1)/2)*28,startX:x,vx:0,vy:470,radius:18,life:2,damage:damage*a.fighter.power,force,color,maxDistance:Infinity,trail:[],trailTime:0})}}}
function updateFlightEffect(p,dt){if(!["bullet","arrow","orb","disc","spark","shard","slash","beam","rocket","wave"].includes(p.style))return;p.flightAge=(p.flightAge||0)+dt;p.effectTime=(p.effectTime||0)+dt;if(p.style==="orb")p.vy+=Math.sin(p.flightAge*9+p.phase)*34*dt;if(p.style==="disc")p.vy+=Math.sin(p.flightAge*13+p.phase)*90*dt;if(p.style==="spark")p.vy+=Math.sin(p.flightAge*32+p.phase)*460*dt;if(p.style==="rocket")p.vx*=1+dt*.85;if(p.style==="wave")p.radius=(p.baseRadius||p.radius)*(1+Math.min(.55,p.flightAge*.42));const interval=p.style==="beam"?.025:p.style==="rocket"?.04:p.style==="bullet"?.075:.055;if(p.effectTime>=interval){p.effectTime=0;const behind=-Math.sign(p.vx||1)*(p.radius+5),size=p.style==="rocket"?9:p.style==="beam"?6:Math.max(3,p.radius*.35);particles.push({x:p.x+behind,y:p.y+(Math.random()-.5)*p.radius,vx:-p.vx*.035,vy:(Math.random()-.5)*35,life:p.style==="orb"?.28:.18,size,color:p.style==="rocket"?"#d8d6d1":p.color})}}
function castCue(a,kind){const size=kind===3?92:kind===2?48:30,life=kind===3?.62:.3;projectiles.push({owner:a,style:"castRing",x:a.x,y:a.y,vx:0,vy:0,radius:8,maxRadius:size,age:0,life,maxLife:life,damage:0,force:0,color:a.fighter.accent});burst(a.x+a.facing*28,a.y,a.fighter.accent,kind===3?26:kind===2?12:6);if(kind===3)shake=12}
function reverseShot(a,style,speed,offset,radius,life,damage,force,color,range){const face=a.facing;shot(a,style,speed,offset,radius,life,damage,force,color,a.x+face*42,a.y,range);a.facing=-face;shot(a,style,speed,-offset,radius,life,damage,force,color,a.x-face*42,a.y,range);a.facing=face}
function signatureUltimate(a,f){const color=f.accent,w=f.weapon;if(f.id==="sol"){areaAttack(a,275,31,760);reverseShot(a,"beam",940,0,24,.8,18,620,color,600);return true}if(f.id==="iris"){castMove(a,{mode:"pull",radius:330,damage:22,force:820});castMove(a,{mode:"mark",delay:.8,radius:235,damage:24,force:740});return true}if(f.id==="bloom"){castMove(a,{mode:"spread",style:"shard",count:11,spread:360,speed:600,radius:12,life:1.5,damage:7,force:300});areaAttack(a,235,20,560);return true}if(w==="blade"||w==="katana"){a.vx=a.facing*520;for(const offset of[-95,0,95])shot(a,"slash",820,offset,25,.65,10,470,color,a.x+a.facing*48,a.y+offset*.08,430);return true}if(w==="spear"){a.vx=a.facing*430;shot(a,"beam",1150,0,28,.72,29,780,color,a.x+a.facing*52,a.y,700);return true}if(w==="hammer"){areaAttack(a,315,34,900);reverseShot(a,"wave",560,0,26,1.2,11,520,color,470);return true}if(w==="shield"){a.invuln=1.8;areaAttack(a,285,29,980);return true}if(w==="glove"){a.vx=a.facing*600;areaAttack(a,225,29,760);shot(a,"wave",650,0,24,.75,13,560,color,a.x+a.facing*48,a.y,300);return true}if(w==="pistol"||w==="rifle"){castMove(a,{mode:"recoil",style:"bullet",count:11,spread:300,speed:960,radius:8,life:1.2,damage:5.5,force:270,recoil:380});shot(a,"beam",1200,0,16,.65,17,610,color,a.x+a.facing*45,a.y,650);return true}if(w==="bow"){castMove(a,{mode:"rain",count:9,damage:12,force:470});castMove(a,{mode:"spread",style:"arrow",count:5,spread:220,speed:820,radius:10,life:1.4,damage:7,force:300});return true}if(w==="cannon"){shot(a,"rocket",470,0,34,2,34,900,color,a.x+a.facing*54,a.y,590);castMove(a,{mode:"mine",delay:.9,radius:190,damage:20,force:620});return true}if(w==="wand"){castMove(a,{mode:"rain",count:8,damage:12,force:460});castMove(a,{mode:"spread",style:"spark",count:7,spread:260,speed:720,radius:12,life:1.3,damage:7,force:280});return true}if(w==="ring"){for(const offset of[-75,75]){shot(a,"disc",680,offset,18,2.4,11,390,color,a.x+a.facing*42,a.y+offset*.12,390);const p=projectiles[projectiles.length-1];p.canReturn=true;p.returnRange=390}return true}if(w==="flask"){for(const d of[80,150,220])projectiles.push({owner:a,style:"mine",x:Math.max(35,Math.min(WORLD_W-35,a.x+a.facing*d)),y:FLOOR-16,vx:0,vy:0,radius:16,blastRadius:175,age:0,life:1.7,delay:1.45+d/900,damage:20*f.power,force:620,color});return true}return false}
function attack(a,kind){const slot=kind-1;if(!roundLive||a.skillDelay[slot]>0||a.hurt>0||a.ko||a.ultimate)return;const f=a.fighter,cost=f.costs[slot];if(a.energy<cost){if(!a.isAI)tone(110,.08,"square");return}a.energy-=cost;a.skillDelay[slot]=f.delays[slot];a.attackPose=kind===3?.65:.28;castCue(a,kind);const target=a===player?enemy:player;if(f.id==="ember"){if(kind===1)shot(a,"fireball",580,0,15,2.2,7,370,f.accent,a.x+a.facing*32,a.y-2,360);if(kind===2)projectiles.push({owner:a,style:"mark",x:target.x,y:target.y,vx:0,vy:0,radius:6,maxRadius:28,blastRadius:170,age:0,life:2.12,delay:2,damage:20,force:520,color:"#ff362b"});if(kind===3){a.ultimate="rise";a.ultTime=0;a.ultTrail=[];a.ultTrailTime=0;a.vy=-980;a.vx=0;a.invuln=1.35}}else if(kind===3){if(!signatureUltimate(a,f))castMove(a,f.kit[slot])}else castMove(a,f.kit[slot]);tone(kind===3?95:190+kind*80,kind===3?.38:.1,kind===3?"sawtooth":"square")}
function showDamage(target,damage){const amount=Math.max(1,damage),active=damageTexts.find(d=>d.target===target&&d.life>0);if(active){active.value+=amount;active.life=.82;active.x=target.x;return}damageTexts.push({target,x:target.x,y:target.y-34,value:amount,life:.82})}
function hit(target,source,damage,force){if(target.invuln>0||target.ko)return;const dealt=Math.min(target.hp,damage);target.hp=Math.max(0,target.hp-damage);showDamage(target,dealt);target.hurt=.24;target.flash=.13;target.vx=Math.sign(target.x-source.x||source.facing)*force*(1+(target.maxHp-target.hp)/(target.maxHp*1.8));target.vy=-220-force*.18;if(source===player)hits++;shake=Math.min(18,5+damage*.45);burst(target.x,target.y,source.fighter.accent,14);tone(75+damage*4,.08,"square");if(target.hp<=0)finish(target===enemy)}
function slash(x,y,face,color,scale){for(let i=0;i<12;i++)particles.push({x:x+Math.random()*18*face,y:y+(Math.random()-.5)*65,vx:face*(180+Math.random()*260),vy:(Math.random()-.5)*180,life:.22+Math.random()*.18,size:(3+Math.random()*7)*scale,color})}
function burst(x,y,color,n){for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,s=100+Math.random()*400;particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.25+Math.random()*.35,size:3+Math.random()*8,color})}}
function projectileImpact(p){const colors={fireball:["#ffd75a","#ff5a35"],mark:["#fff17a","#ff2b20"],meteor:["#fff17a","#ff321c","#7c120f"]}[p.style]||[p.color];colors.forEach((c,i)=>burst(p.x,p.y,c,7+i*3));projectiles.push({owner:p.owner,style:"impactRing",x:p.x,y:p.y,vx:0,vy:0,radius:5,maxRadius:Math.max(32,(p.radius||10)*2.8),age:0,life:.3,maxLife:.3,damage:0,force:0,color:p.color||"#fff"})}
function guideReturningProjectile(p,dt){if(!p.canReturn||!p.returning)return false;p.life=Math.max(p.life,1.25);const dx=p.owner.x-p.x,dy=p.owner.y-p.y,distance=Math.hypot(dx,dy);if(distance<=p.owner.radius+12){burst(p.owner.x,p.owner.y,p.color,8);p.life=0;return true}const speed=Math.max(520,Math.hypot(p.vx,p.vy)),targetVx=dx/distance*speed,targetVy=dy/distance*speed,turn=Math.min(1,10*dt);p.vx+=(targetVx-p.vx)*turn;p.vy+=(targetVy-p.vy)*turn;p.maxDistance=Infinity;return false}
function preserveFireTrail(p){for(const point of p.trail||[]){const life=Math.max(.04,point.life||0);particles.push({x:point.x,y:point.y,vx:0,vy:0,life,size:point.size||14,color:point.color||"#ff596a"})}}
function explodeFireball(p,applySplash=false){const radius=150,target=p.owner===player?enemy:player;preserveFireTrail(p);projectiles.push({owner:p.owner,style:"fireBurst",x:p.x,y:p.y,vx:0,vy:0,radius:14,maxRadius:radius,age:0,life:.52,damage:0,force:0,color:"#ef0808"});if(applySplash){const distance=Math.hypot(target.x-p.x,target.y-p.y);if(distance<radius)hit(target,p.owner,radialDamage(7,distance,radius),260)}tone(145,.07,"square")}

function radialDamage(base,distance,radius){return Math.max(3,Math.round(base*(1-.85*Math.min(1,distance/radius))))}
function ultimateImpact(a){const target=a===player?enemy:player,radius=300,distance=Math.abs(target.x-a.x);projectiles.push({owner:a,style:"ultBlast",x:a.x,y:FLOOR,vx:0,vy:0,radius:24,maxRadius:radius,age:0,life:.58,damage:0,force:0,color:"#ff1717"});if(distance<radius)hit(target,a,radialDamage(31,distance,radius),760);shake=24;burst(a.x,FLOOR-18,"#ff2525",32);tone(70,.42,"sawtooth")}
function updateActor(a,dt){a.skillDelay=a.skillDelay.map(v=>Math.max(0,v-dt));a.hurt=Math.max(0,a.hurt-dt);a.flash=Math.max(0,a.flash-dt);a.attackPose=Math.max(0,a.attackPose-dt);a.invuln=Math.max(0,a.invuln-dt);if(!roundLive||a.ko)return;a.energy=Math.min(100,a.energy+5.5*dt);a.ultTrail.forEach(t=>t.life-=dt);a.ultTrail=a.ultTrail.filter(t=>t.life>0);if(a.ultimate){a.ultTime+=dt;if(a.ultimate==="rise"&&a.vy>=-40){a.ultimate="fall";a.ultTime=0;a.ultTrailTime=0;a.vy=260}else if(a.ultimate==="impact"&&a.ultTime>=.58){a.ultimate=null;a.ultTime=0}if(a.ultimate==="rise"||a.ultimate==="fall"){a.ultTrailTime+=dt;while(a.ultTrailTime>=.055){a.ultTrailTime-=.055;a.ultTrail.unshift({x:a.x,y:a.y,life:.5});if(a.ultTrail.length>12)a.ultTrail.pop()}}}let move=0;
 if(a.isRemote){if(remoteKeys.a)move--;if(remoteKeys.d)move++;if(remotePressed.w&&a.onGround){a.vy=-650;a.onGround=false}if(remotePressed.e)attack(a,1);if(remotePressed.r)attack(a,2);if(remotePressed.t)attack(a,3);for(const k in remotePressed)delete remotePressed[k]}
 else if(!a.isAI){if(keys.a)move--;if(keys.d)move++;if(pressed.w&&a.onGround){a.vy=-650;a.onGround=false;tone(220,.06,"square")}if(pressed.e)attack(a,1);if(pressed.r)attack(a,2);if(pressed.t)attack(a,3)}
 else{a.aiThink-=dt;const dx=player.x-a.x;if(Math.abs(dx)>95)move=Math.sign(dx);if(Math.abs(dx)<48)move=-Math.sign(dx);if(a.aiThink<=0){a.aiThink=.18+Math.random()*.45;if(a.onGround&&(Math.random()<.2||player.y<a.y-60))a.vy=-630;const d=Math.abs(dx);if(a.energy>=a.fighter.costs[2]&&d<520&&Math.random()<.35)attack(a,3);else if(a.energy>=a.fighter.costs[1]&&d<400&&Math.random()<.45)attack(a,2);else if(d<570&&Math.random()<.65)attack(a,1)}}
 if(move&&a.hurt<=0){if(a.ultimate){const targetVx=move*150;a.vx+=(targetVx-a.vx)*Math.min(1,7*dt)}else a.vx+=move*a.fighter.speed*8*dt;a.facing=move}else if(a.ultimate)a.vx*=Math.pow(.03,dt);const maxSpeed=a.ultimate?155:a.fighter.speed;a.vx=Math.max(-maxSpeed,Math.min(maxSpeed,a.vx));a.vy+=GRAVITY*dt;a.x+=a.vx*dt;a.y+=a.vy*dt;a.vx*=Math.pow(a.onGround?.0008:.25,dt);const p=platformAt(a.x,a.y,a.vy);if(p&&a.vy>=0&&a.y+a.radius>=p.y&&a.y+a.radius-p.y<55){a.y=p.y-a.radius;a.vy=0;a.onGround=true;if(a.ultimate==="fall"){a.ultimate="impact";a.ultTime=0;ultimateImpact(a)}}else a.onGround=false;if(a.x<38){a.x=38;a.vx=Math.abs(a.vx)*.5}if(a.x>WORLD_W-38){a.x=WORLD_W-38;a.vx=-Math.abs(a.vx)*.5}if(a.y>H+80){a.hp=Math.max(0,a.hp-18);a.ultimate=null;if(a.hp<=0){finish(a===enemy);return}a.x=a===player?100:1080;a.y=120;a.vx=0;a.vy=0;a.invuln=1;burst(a.x,FLOOR,"#fff",16)}}
