function update(dt){if(mode!=="battle"||paused)return;if(battleType==="online"&&netRole==="guest"){for(const k in pressed)delete pressed[k];return}if(roundLive){elapsed+=dt;matchTime=Math.max(0,99-elapsed);if(matchTime<=0)finish(player.hp>=enemy.hp)}updateActor(player,dt);updateActor(enemy,dt);for(const p of projectiles){if(p.style==="fireball"){p.trail??=[];p.trail.forEach(t=>t.life-=dt);p.trail=p.trail.filter(t=>t.life>0);const progress=Math.min(1,Math.abs(p.x-p.startX)/p.maxDistance),direction=Math.sign(p.vx||1),speed=Math.max(150,580*(1-progress*.74)),sampleDelay=.045+progress*.035;p.trailTime=(p.trailTime||0)+dt;while(p.trailTime>=sampleDelay){p.trailTime-=sampleDelay;const life=.34-progress*.1,size=22-progress*8,index=Math.min(6,Math.floor(progress*7));p.trail.unshift({x:p.x,y:p.y,life,maxLife:life,size:22-progress*8,color:["#e90b18","#f52234","#ff4052","#ff6071","#ff7d8c","#ff98a5","#ffafba"][index]});if(p.trail.length>8)p.trail.pop()}p.vx=direction*speed}if(guideReturningProjectile(p,dt))continue;updateFlightEffect(p,dt);p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;if(p.delay!==undefined)p.delay-=dt;const t=p.owner===player?enemy:player;if(p.style==="castRing"||p.style==="impactRing"){p.age+=dt;if(p.style==="castRing"){p.x=p.owner.x;p.y=p.owner.y}const grow=Math.min(1,p.age/(p.maxLife||.4));p.radius=5+(p.maxRadius-5)*(1-(1-grow)*(1-grow));continue}if(p.style==="blast"){p.age+=dt;const grow=Math.min(1,p.age/.58),ease=1-(1-grow)*(1-grow);p.radius=14+(p.maxRadius-14)*ease;continue}if(p.style==="fireBurst"){p.age+=dt;const grow=Math.min(1,p.age/.52),ease=1-(1-grow)*(1-grow);p.radius=14+(p.maxRadius-14)*ease;continue}if(p.style==="ultBlast"){p.age+=dt;const grow=Math.min(1,p.age/.58),ease=1-(1-grow)*(1-grow);p.radius=24+(p.maxRadius-24)*ease;continue}if(p.style==="shield"){p.age=(p.age||0)+dt;p.x=p.owner.x;p.y=p.owner.y;p.radius=42+Math.sin(p.age*12)*4;continue}if(p.style==="mark"||p.style==="mine"){p.age+=dt;if(p.style==="mark"){const grow=Math.min(1,p.age/(p.delay+p.age||2));p.radius=6+(p.maxRadius-6)*(grow*grow*(3-2*grow))}else p.radius=15+Math.sin(p.age*14)*3;if(p.delay<=0){const radius=p.blastRadius||170,distance=Math.hypot(t.x-p.x,t.y-p.y);projectiles.push({owner:p.owner,style:"blast",x:p.x,y:p.y,vx:0,vy:0,radius:14,maxRadius:radius,age:0,life:.58,damage:0,force:0,color:p.color});shake=16;if(distance<radius)hit(t,p.owner,radialDamage(p.damage||20,distance,radius),p.force);p.life=0}continue}if(p.style==="meteor"){if(p.y>=FLOOR-35){projectileImpact(p);burst(p.x,p.y,p.color||"#ffcd3d",26);shake=22;if(Math.abs(t.x-p.x)<210)hit(t,p.owner,p.damage,p.force);p.life=0}continue}if(p.maxDistance<Infinity&&Math.abs(p.x-p.startX)>=p.maxDistance){if(p.canReturn&&!p.returning){p.returning=true;p.vx=-p.vx*.9;p.startX=p.x;p.maxDistance=Infinity;continue}if(p.style==="fireball")explodeFireball(p,true);else projectileImpact(p);p.life=0;continue}if(p.life>0&&!p.hitTarget&&Math.hypot(p.x-t.x,p.y-t.y)<p.radius+t.radius){if(p.style==="fireball")explodeFireball(p);else projectileImpact(p);hit(t,p.owner,p.damage,p.force);if(p.canReturn&&!p.returning){p.returning=true;p.hitTarget=true;p.vx=-p.vx*.9;p.startX=p.x;p.maxDistance=Infinity;p.damage*=.72}else p.life=0}}projectiles=projectiles.filter(p=>p.life>0&&p.x>-320&&p.x<WORLD_W+320&&p.y>-400&&p.y<H+320);particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.94;p.vy*=.94;p.life-=dt});particles=particles.filter(p=>p.life>0);damageTexts.forEach(d=>{d.life-=dt});damageTexts=damageTexts.filter(d=>d.life>0);shake*=Math.pow(.008,dt);updateBattleUI();sendState(performance.now());for(const k in pressed)delete pressed[k]}
