function drawScythe(g,f){g.save();g.rotate(-.34);g.strokeStyle="#080a0e";g.lineCap="round";g.lineWidth=11;g.beginPath();g.moveTo(-17,25);g.lineTo(43,-20);g.stroke();g.strokeStyle="#9a7d58";g.lineWidth=5;g.stroke();g.fillStyle=f.accent;g.strokeStyle="#080a0e";g.lineWidth=6;g.beginPath();g.moveTo(38,-24);g.quadraticCurveTo(77,-42,91,-15);g.quadraticCurveTo(69,-24,48,-5);g.closePath();g.fill();g.stroke();circle(g,-12,21,8,f.color,"#080a0e",5);g.restore()}
function drawWateringCan(g,f){g.save();g.fillStyle=f.accent;g.strokeStyle="#080a0e";g.lineWidth=6;g.beginPath();g.roundRect(-7,-13,45,35,7);g.fill();g.stroke();g.beginPath();g.arc(15,-11,22,Math.PI,Math.PI*2);g.stroke();g.beginPath();g.moveTo(36,-4);g.lineTo(67,-18);g.lineTo(72,-8);g.lineTo(39,8);g.closePath();g.fill();g.stroke();g.fillStyle="#dfffe9";for(let i=0;i<3;i++)circle(g,76+i*6,-15+i*5,3,"#dfffe9",null,0);g.restore()}
function drawWeaponDetails(g,f){g.save();g.shadowColor=f.accent;g.shadowBlur=5;g.strokeStyle="#fff";g.fillStyle="#fff";g.globalAlpha=.72;if(["pistol","rifle","cannon"].includes(f.weapon)){g.lineWidth=2;g.beginPath();g.moveTo(-1,-5);g.lineTo(30,-7);g.stroke();circle(g,4,5,3,"#ffd34e","#090b10",2);circle(g,25,4,2,f.accent,"#090b10",1)}else if(f.weapon==="bow"){circle(g,15,0,5,f.accent,"#090b10",2);g.beginPath();g.moveTo(20,-25);g.lineTo(25,-18);g.stroke()}else if(f.weapon==="hammer"){g.fillStyle="#fff1a3";g.fillRect(43,-18,6,30);circle(g,48,-3,5,f.accent,"#090b10",2)}else if(f.weapon==="spear"){g.lineWidth=3;g.beginPath();g.moveTo(10,3);g.lineTo(45,-12);g.stroke();circle(g,3,6,5,f.accent,"#090b10",2)}else if(f.weapon==="blade"||f.weapon==="katana"){circle(g,28,-2,4,"#fff",f.accent,2)}else if(f.weapon==="shield"){circle(g,12,1,12,"#252938",f.accent,4);circle(g,12,1,4,"#fff",null,0)}else if(f.weapon==="glove"){for(let i=0;i<3;i++)circle(g,23+i*7,-12+i*2,5,f.accent,"#090b10",2)}else if(f.weapon==="flask"){circle(g,10,12,4,"#fff",null,0);circle(g,20,18,3,"#fff",null,0)}else if(f.weapon==="ring"){for(let i=0;i<4;i++){const a=i*Math.PI/2;circle(g,13+Math.cos(a)*25,1+Math.sin(a)*25,4,"#fff",f.accent,2)}}else if(f.weapon==="wand"){circle(g,42,-17,8,"#fff",f.accent,3)}else{circle(g,12,0,7,"#fff",f.accent,2)}g.restore()}
function weaponMotion(g,f,pose){if(pose<=0)return;const raw=1-Math.min(1,pose/.28),phase=raw*raw*(3-2*raw),impact=Math.sin(Math.min(1,raw*1.3)*Math.PI);if(["blade","katana","hammer","scythe"].includes(f.weapon)){const angle=-1.02+phase*1.72;g.translate(-7+phase*13,-13+phase*22);g.rotate(angle)}else if(f.weapon==="spear"){const thrust=Math.sin(Math.min(1,raw*1.45)*Math.PI);g.translate(34*thrust,-7*thrust);g.rotate(-.18*thrust)}else if(f.weapon==="shield"){g.translate(22*impact,-3*impact);g.rotate(-.12*impact)}else if(f.weapon==="glove"){g.translate(31*impact,-9*impact);g.scale(1+impact*.12,1+impact*.12)}else if(f.weapon==="boomerang"){g.translate(18*impact,-12*impact);g.rotate(-.55*impact)}else{g.translate(-6*impact,-4*impact);g.rotate(-.16*impact)}}
function drawWeapon(g,f,pose=0){g.save();g.translate(34,2);weaponMotion(g,f,pose);g.scale(1.34,1.34);g.lineCap="round";g.lineJoin="round";g.strokeStyle="#080a0e";g.fillStyle=f.accent;g.lineWidth=7;let detailed=true;if(["pistol","rifle","cannon","bow"].includes(f.weapon))drawDetailedRanged(g,f);else if(f.weapon==="hammer"){g.rotate(-.32);g.fillStyle="#6f5139";g.fillRect(-8,-7,57,14);g.strokeRect(-8,-7,57,14);g.fillStyle=f.accent;g.beginPath();g.moveTo(35,-27);g.lineTo(67,-25);g.lineTo(74,-5);g.lineTo(65,19);g.lineTo(35,18);g.closePath();g.fill();g.stroke();g.fillStyle="#fff1a3";g.globalAlpha=.55;g.fillRect(44,-18,18,5);g.globalAlpha=1}else if(f.weapon==="spear")drawDetailedSpear(g,f);else if(f.weapon==="blade"||f.weapon==="katana")drawDetailedBlade(g,f);else if(f.weapon==="shield"){g.fillStyle=f.accent;g.beginPath();g.moveTo(-3,-28);g.quadraticCurveTo(38,-25,43,0);g.quadraticCurveTo(35,30,8,39);g.quadraticCurveTo(-10,17,-3,-28);g.closePath();g.fill();g.stroke();circle(g,12,2,13,"#303642","#080a0e",6);circle(g,12,2,5,"#fff2a0",null,0)}else if(f.weapon==="glove"){detailed=false;g.fillStyle=f.accent;g.beginPath();g.moveTo(-5,9);g.lineTo(1,-16);g.lineTo(13,-22);g.lineTo(22,-12);g.lineTo(32,-19);g.lineTo(41,-8);g.lineTo(37,12);g.lineTo(20,25);g.lineTo(3,22);g.closePath();g.fill();g.stroke();for(let i=0;i<3;i++)circle(g,13+i*10,-8-i%2*3,5,"#fff1a3","#080a0e",3)}else if(f.weapon==="flask"){g.fillStyle="#dffcff";g.beginPath();g.moveTo(5,-26);g.lineTo(28,-26);g.lineTo(28,-6);g.quadraticCurveTo(48,22,16,32);g.quadraticCurveTo(-17,22,5,-6);g.closePath();g.fill();g.stroke();g.fillStyle=f.accent;g.beginPath();g.moveTo(-4,13);g.quadraticCurveTo(16,5,37,13);g.quadraticCurveTo(38,27,16,29);g.quadraticCurveTo(-5,27,-4,13);g.fill();g.stroke()}else if(f.weapon==="boomerang"){detailed=false;drawBoomerang(g,f)}else if(f.weapon==="scythe"){detailed=false;drawScythe(g,f)}else if(f.weapon==="wateringcan"){detailed=false;drawWateringCan(g,f)}else if(f.weapon==="wand")drawDetailedWand(g,f);else{g.beginPath();g.moveTo(-8,17);g.lineTo(35,-20);g.stroke()}if(detailed)drawWeaponDetails(g,f);g.restore()}
function drawFighter(g,x,y,s,f,face,pose,portrait=false,fireReady=true){g.save();g.translate(x,y);g.scale(face*s,s);g.translate(0,portrait?0:Math.sin(performance.now()/110)*1.5);g.imageSmoothingEnabled=false;
 if(f.id==="ember"){if(fireReady&&mageSprite.complete&&mageSprite.naturalWidth)g.drawImage(mageSprite,-34,-42,106,84);else circle(g,0,0,34,f.color,"#050507",9)}else{circle(g,0,0,34,f.color,"#050507",9);drawWeapon(g,f,pose)}
 g.restore()}
const drawDetailedRangedBase=drawDetailedRanged;
drawDetailedRanged=function(g,f){if(f.id==="moss")return drawMossRifle(g,f);if(f.id==="jet")return drawJetGun(g,f);return drawDetailedRangedBase(g,f)};
function drawPlayerTag(g,x,y,text){g.save();g.font="900 28px Impact, Arial Black, sans-serif";g.textAlign="center";g.textBaseline="bottom";g.lineJoin="round";g.lineWidth=6;g.strokeStyle="#f7ffff";g.strokeText(text,x,y);g.fillStyle="#28e1e7";g.fillText(text,x,y);g.restore()}
function drawDamageNumbers(g){g.save();g.font="900 24px Arial Black, sans-serif";g.textAlign="center";g.textBaseline="middle";g.lineJoin="round";for(const d of damageTexts){const value=String(Math.round(d.value));g.globalAlpha=Math.min(1,d.life*2.5);g.lineWidth=5;g.strokeStyle="#3b0000";g.strokeText(value,d.x,d.y);g.fillStyle="#ff1717";g.fillText(value,d.x,d.y)}g.restore()}
function drawFireTrail(g,p){if(!p.trail?.length)return;g.save();for(let i=p.trail.length-1;i>=0;i--){const point=p.trail[i],life=Math.max(0,Math.min(1,point.life/(point.maxLife||.34))),size=(point.size||16)*(.58+life*.42);g.globalAlpha=life*(i===0?.9:.72);g.fillStyle=point.color||"#ff596a";g.fillRect(point.x-size/2,point.y-size/2,size,size)}g.restore()}
