function drawProjectile(g,p,now){g.save();g.translate(p.x,p.y);g.rotate(Math.atan2(p.vy,p.vx));g.fillStyle=p.color;g.strokeStyle=p.color;g.shadowColor=p.color;g.shadowBlur=16;const r=p.radius;
 if(p.style==="fireball"){g.shadowBlur=0;g.scale(.8,.8);g.fillStyle="#ef0808";g.beginPath();g.moveTo(-7,-25);g.lineTo(22,-25);g.lineTo(34,-17);g.lineTo(40,-4);g.lineTo(36,14);g.lineTo(24,25);g.lineTo(-8,22);g.lineTo(-20,12);g.lineTo(-12,2);g.lineTo(-22,-8);g.lineTo(-9,-13);g.closePath();g.fill();g.fillStyle="#fff000";g.beginPath();g.moveTo(10,-12);g.lineTo(26,-9);g.lineTo(31,0);g.lineTo(27,11);g.lineTo(12,14);g.lineTo(18,5);g.lineTo(5,0);g.lineTo(17,-2);g.closePath();g.fill()}
 else if(p.style==="mark"){g.shadowBlur=0;g.fillStyle=p.color;g.beginPath();for(let i=0;i<16;i++){const a=-Math.PI/2+i*Math.PI/8,rr=i%2?r*.46:r;g.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}g.closePath();g.fill();g.fillStyle="#fff36a";g.beginPath();for(let i=0;i<16;i++){const a=-Math.PI/2+i*Math.PI/8,rr=i%2?r*.16:r*.34;g.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}g.closePath();g.fill()}
 else if(p.style==="castRing"||p.style==="impactRing"){const fade=Math.max(0,p.life/(p.maxLife||.4));g.globalAlpha=fade;g.shadowBlur=10;g.strokeStyle=p.color;g.lineWidth=Math.max(3,r*.08);circle(g,0,0,r,"transparent",p.color,g.lineWidth);if(p.style==="castRing"){g.rotate(now/260);for(let i=0;i<8;i++){g.rotate(Math.PI/4);g.beginPath();g.moveTo(r*.68,0);g.lineTo(r*.94,0);g.stroke()}circle(g,0,0,r*.48,"transparent","#fff",Math.max(2,r*.025))}else{circle(g,0,0,r*.62,"transparent","#fff",Math.max(2,r*.04))}}
 else if(p.style==="blast"){g.globalAlpha=Math.max(0,p.life/.58)*.46;g.shadowBlur=0;circle(g,0,0,r,p.color,null,0)}
 else if(p.style==="fireBurst"){g.shadowBlur=0;g.globalAlpha=Math.max(0,p.life/.52)*.46;circle(g,0,0,r,"#ef3038",null,0)}
 else if(p.style==="ultBlast"){g.globalAlpha=Math.max(0,p.life/.58)*.82;g.shadowBlur=0;g.scale(1,1.05);circle(g,0,0,r,p.color,null,0)}
 else if(p.style==="shield"){g.shadowBlur=8;g.globalAlpha=Math.min(.78,p.life);circle(g,0,0,r,"transparent",p.color,8)}
 else if(p.style==="bullet"){g.shadowBlur=7;g.fillRect(-r*1.8,-r*.48,r*3.6,r*.96);g.fillStyle="#fff";g.fillRect(r*.15,-r*.22,r*1.25,r*.44)}
 else if(p.style==="arrow"){g.shadowBlur=5;g.lineWidth=Math.max(4,r*.45);g.beginPath();g.moveTo(-r*2.2,0);g.lineTo(r*1.8,0);g.stroke();g.beginPath();g.moveTo(r*2.1,0);g.lineTo(r*.7,-r);g.lineTo(r*.7,r);g.closePath();g.fill()}
 else if(p.style==="orb"){circle(g,0,0,r,p.color,"#090b10",4);circle(g,r*.18,-r*.2,r*.42,"#fff",null,0)}
 else if(p.style==="disc"){g.shadowBlur=8;g.strokeStyle="#080a0e";g.lineWidth=Math.max(4,r*.3);g.beginPath();g.moveTo(-r*1.15,-r*.85);g.lineTo(0,0);g.lineTo(-r*1.15,r*.85);g.lineTo(-r*.72,r*1.15);g.lineTo(r*.55,0);g.lineTo(-r*.72,-r*1.15);g.closePath();g.fill();g.stroke();g.strokeStyle="#fff";g.globalAlpha=.65;g.lineWidth=2;g.beginPath();g.moveTo(-r*.58,-r*.55);g.lineTo(r*.08,0);g.lineTo(-r*.58,r*.55);g.stroke()}
 else if(p.style==="seed"){g.rotate(now/170);g.fillStyle="#7a4b22";g.strokeStyle="#20301f";g.lineWidth=4;g.beginPath();g.ellipse(0,0,r*1.2,r*.72,0,0,Math.PI*2);g.fill();g.stroke();g.fillStyle="#77df62";g.beginPath();g.ellipse(r*.1,-r*.75,r*.65,r*.28,-.5,0,Math.PI*2);g.fill()}
 else if(p.style==="thorn"){g.fillStyle=p.color;g.strokeStyle="#183521";g.lineWidth=4;g.beginPath();g.moveTo(r*1.6,0);g.lineTo(-r*.65,-r*.75);g.lineTo(-r*.25,0);g.lineTo(-r*.65,r*.75);g.closePath();g.fill();g.stroke()}
 else if(p.style==="spark"){g.rotate(now/120);g.beginPath();for(let i=0;i<16;i++){const a=i*Math.PI/8,rr=i%2?r*.35:r*1.45;g.lineTo(Math.cos(a)*rr,Math.sin(a)*rr)}g.closePath();g.fill();g.fillStyle="#fff";circle(g,0,0,r*.35,"#fff",null,0)}
 else if(p.style==="shard"){g.rotate(Math.PI/4);g.fillRect(-r*.8,-r*.8,r*1.6,r*1.6);g.strokeStyle="#fff";g.lineWidth=3;g.strokeRect(-r*.55,-r*.55,r*1.1,r*1.1)}
 else if(p.style==="slash"){g.shadowBlur=9;g.lineWidth=Math.max(7,r*.5);g.beginPath();g.arc(0,0,r*1.5,-1.15,1.15);g.stroke();g.strokeStyle="#fff";g.lineWidth=Math.max(2,r*.12);g.stroke()}
 else if(p.style==="beam"){g.shadowBlur=12;g.fillRect(-r*2.4,-r*.55,r*4.8,r*1.1);g.fillStyle="#fff";g.fillRect(-r*2.2,-r*.16,r*4.4,r*.32)}
 else if(p.style==="rocket"){g.shadowBlur=8;g.beginPath();g.moveTo(r*1.8,0);g.lineTo(r*.6,-r);g.lineTo(-r,-r*.65);g.lineTo(-r*1.35,0);g.lineTo(-r,r*.65);g.lineTo(r*.6,r);g.closePath();g.fill();g.fillStyle="#ffd84a";g.beginPath();g.moveTo(-r*1.2,-r*.45);g.lineTo(-r*2.2,0);g.lineTo(-r*1.2,r*.45);g.closePath();g.fill()}
 else if(p.style==="wave"){g.shadowBlur=8;g.lineWidth=Math.max(6,r*.35);g.beginPath();g.arc(-r*.4,0,r*1.25,-1.05,1.05);g.stroke();g.beginPath();g.arc(r*.25,0,r*.75,-1.05,1.05);g.stroke()}
 else if(p.style==="mine"){g.shadowBlur=8;g.rotate(now/220);g.fillStyle="#17101e";circle(g,0,0,r,"#17101e",p.color,4);g.fillStyle=p.color;for(let i=0;i<8;i++){g.rotate(Math.PI/4);g.fillRect(r*.72,-3,r*.75,6)}circle(g,0,0,r*.38,p.delay<.55?"#fff35b":p.color,"#fff",2)}
 else if(p.style==="meteor"){g.rotate(now/180);g.beginPath();g.moveTo(-r*1.8,0);g.lineTo(-r*.65,-r*.75);g.arc(0,0,r,-2.3,2.3);g.closePath();g.fill();circle(g,r*.1,-r*.15,r*.55,"#ffcf38",null,0);g.strokeStyle="#7c120f";g.lineWidth=5;g.beginPath();g.moveTo(-r*.35,-r*.45);g.lineTo(r*.25,r*.45);g.moveTo(r*.4,-r*.2);g.lineTo(-r*.1,r*.2);g.stroke()}
 else{g.beginPath();g.arc(0,0,r,0,Math.PI*2);g.fill()}g.restore()}
function drawUltimateMotion(g,a){if(!a.ultimate)return;g.save();g.translate(a.x,a.y);g.imageSmoothingEnabled=false;if(a.ultimate==="rise"&&ultimateRiseSprite.complete&&ultimateRiseSprite.naturalWidth){g.drawImage(ultimateRiseSprite,0,0,228,180,-57,-74,114,90);g.restore();return}if((a.ultimate==="fall"||a.ultimate==="impact")&&ultimateFallSprite.complete&&ultimateFallSprite.naturalWidth){g.drawImage(ultimateFallSprite,0,532,224,230,-32,-35,65,67);g.restore();return}const rising=a.ultimate==="rise",dir=rising?1:-1;g.globalAlpha=.6;g.fillStyle="#ff604e";g.beginPath();g.moveTo(-13,dir*-14);g.lineTo(-48,dir*-34);g.lineTo(-62,dir*2);g.lineTo(-31,dir*26);g.lineTo(0,dir*12);g.lineTo(31,dir*26);g.lineTo(62,dir*2);g.lineTo(48,dir*-34);g.lineTo(13,dir*-14);g.closePath();g.fill();g.globalAlpha=.95;g.fillStyle="#fff129";g.beginPath();g.moveTo(-17,dir*2);g.lineTo(0,dir*-27);g.lineTo(17,dir*2);g.lineTo(11,dir*22);g.lineTo(-11,dir*22);g.closePath();g.fill();g.restore()}
function render(now){if(player&&(mode==="battle"||mode==="result")){const focusActor=netRole==="guest"?enemy:player,focus=focusActor.x-W/2;cameraX+=(Math.max(0,Math.min(WORLD_W-W,focus))-cameraX)*.08}ctx.save();ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);background(now/1000);if(mode==="battle"||mode==="result"){ctx.save();ctx.translate(-cameraX,0);for(const p of projectiles){if(p.style==="fireball")drawFireTrail(ctx,p);drawProjectile(ctx,p,now)}if(player){if(player.ultimate){drawUltimateTrail(ctx,player);drawUltimateMotion(ctx,player)}else{ctx.globalAlpha=player.flash>0?.35:1;drawFighter(ctx,player.x,player.y,.55,player.fighter,player.facing,player.attackPose,false,player.skillDelay[0]<=0);ctx.globalAlpha=1;drawPlayerTag(ctx,player.x,player.y-32,"1P")}}if(enemy){if(enemy.ultimate){drawUltimateTrail(ctx,enemy);drawUltimateMotion(ctx,enemy)}else{ctx.globalAlpha=enemy.flash>0?.35:1;drawFighter(ctx,enemy.x,enemy.y,.55,enemy.fighter,enemy.facing,enemy.attackPose,false,enemy.skillDelay[0]<=0);ctx.globalAlpha=1;drawPlayerTag(ctx,enemy.x,enemy.y-32,"2P")}}for(const p of particles){ctx.globalAlpha=Math.min(1,p.life*4);ctx.fillStyle=p.color;ctx.fillRect(p.x-p.size/2,p.y-p.size/2,p.size,p.size)}ctx.globalAlpha=1;drawDamageNumbers(ctx);ctx.restore()}ctx.restore()}
function loop(now){const dt=Math.min(.033,(now-last)/1000);last=now;update(dt);render(now);requestAnimationFrame(loop)}
function tone(freq,dur,type="sine"){if(muted)return;try{audioCtx??=new AudioContext;const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.07,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur)}catch{}}
function updateSoundButton(){const b=$("#soundBtn");b.textContent=muted?"효과음 OFF":"효과음 ON";b.classList.toggle("on",!muted);b.setAttribute("aria-label",muted?"효과음 켜기":"효과음 끄기");b.title=muted?"효과음 켜기":"효과음 끄기"}

function sendInput(k,down){if(battleType==="online"&&netRole==="guest"&&conn?.open)conn.send({type:"input",key:k,down})}
$("#playBtn").onclick=()=>showScreen("mode");$("#aiBtn").onclick=()=>showScreen("select");$("#onlineBtn").onclick=()=>showScreen("online");$("#howBtn").onclick=()=>showScreen("how");$("#fightBtn").onclick=()=>showScreen("mapSelect");$("#plainMapBtn").onclick=startBattle;$("#rematchBtn").onclick=()=>battleType==="online"?showScreen("online"):startBattle();$("#createRoomBtn").onclick=createRoom;$("#joinRoomBtn").onclick=joinRoom;$("#copyCodeBtn").onclick=()=>navigator.clipboard.writeText($("#roomCode").textContent).then(()=>networkMessage("방 코드를 복사했습니다."));$("#cancelOnlineBtn").onclick=()=>{closeNetwork();showScreen("mode")};document.querySelectorAll("[data-back]").forEach(b=>b.onclick=()=>showScreen(b.dataset.back));$("#pauseBtn").onclick=()=>{paused=!paused;announce(paused?"PAUSED":"FIGHT!",400)};
$("#soundBtn").onclick=()=>{muted=!muted;localStorage.setItem("riftBounceMuted",String(muted));updateSoundButton();if(!muted)tone(440,.08,"square")};
addEventListener("keydown",e=>{const k=e.key.toLowerCase();if(!keys[k]){pressed[k]=true;sendInput(k,true)}keys[k]=true;if(["a","d","w","e","r","t"].includes(k))e.preventDefault();if(k==="escape"&&mode==="battle")paused=!paused});addEventListener("keyup",e=>{const k=e.key.toLowerCase();keys[k]=false;sendInput(k,false)});
document.querySelectorAll("[data-key]").forEach(b=>{const k=b.dataset.key,down=e=>{e.preventDefault();if(!keys[k]){pressed[k]=true;sendInput(k,true)}keys[k]=true},up=e=>{e.preventDefault();keys[k]=false;sendInput(k,false)};b.addEventListener("pointerdown",down);b.addEventListener("pointerup",up);b.addEventListener("pointercancel",up)});
updateSoundButton();buildRoster();mageSprite.onload=()=>{document.querySelectorAll(".fighter-card canvas").forEach((c,i)=>drawPortrait(c.getContext("2d"),fighters[i]));if(selected===null){drawLargePreview($("#pPreview"),fighters[0],1);drawLargePreview($("#ePreview"),fighters[1],-1)}};mageSprite.src="assets/mage-reference.png?v=2";mageBodySprite.src="assets/mage-body.png?v=1";ultimateRiseSprite.src="assets/ultimate-rise.png?v=1";ultimateFallSprite.src="assets/ultimate-fall.png?v=1";requestAnimationFrame(loop);
